package net.officefloor.hq.app.sheet;

/** A sheet: the id everything else in the app is kept under, and its own today (yyyy-MM-dd). */
public record Sheet(String id, String createdBy, String today) {
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SheetRepository {

    private final JdbcTemplate jdbc;

    public SheetRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet with this id, made (empty, today the real date) if it has never been loaded before. */
    public Sheet open(String id, String user) {
        try {
            jdbc.update("INSERT INTO sheet (id, created_by, today) "
                    + "SELECT ?, ?, ? WHERE NOT EXISTS (SELECT 1 FROM sheet WHERE id = ?)",
                    id, user, LocalDate.now(), id);
        } catch (DuplicateKeyException alreadyMade) {
            // another user made it at the same moment: it is there now
        }
        return find(id);
    }

    /** The sheet's today: the date every date decision and default on the sheet uses. */
    public LocalDate today(String id) {
        Sheet sheet = find(id);
        return sheet == null ? LocalDate.now() : LocalDate.parse(sheet.today());
    }

    public void setToday(String id, LocalDate today) {
        jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", today, id);
    }

    public Sheet find(String id) {
        return jdbc.query("SELECT id, created_by, today FROM sheet WHERE id = ?",
                (rs, n) -> new Sheet(rs.getString("id"), rs.getString("created_by"),
                        rs.getObject("today", LocalDate.class).toString()), id)
                .stream().findFirst().orElse(null);
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class OpenSheet {
    public void open(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            SheetRepository repository, Out<Sheet> sheet) {
        sheet.set(repository.open(sheetId.trim(), by == null ? "" : by));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSheet {
    public void respond(@Val Sheet sheet, ObjectResponse<Sheet> response) {
        response.send(sheet);
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class ApplySheetToday {
    public void apply(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "by", required = false) String by,
            @Val LocalDate today, SheetRepository repository, Out<Sheet> sheet) {
        String id = sheetId.trim();
        repository.open(id, by == null ? "" : by);
        repository.setToday(id, today);
        sheet.set(repository.find(id));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSheetToday {
    public void validate(@RequestBody SheetTodayRequest request, Out<LocalDate> today)
            throws InvalidSheetTodayException {
        String value = request == null || request.today() == null ? "" : request.today().trim();
        try {
            today.set(LocalDate.parse(value));
        } catch (DateTimeParseException e) {
            throw new InvalidSheetTodayException("Not a date: " + value);
        }
    }
}
