# POST /api/sheets/{sheetId}/bulk-open — open the selected claims together, in list order; each that
# cannot be opened is left as it is. Responds with how many were opened and how many refused.
open:
  class: net.officefloor.hq.app.claim.BulkOpenClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkOpen
# POST /api/sheets/{sheetId}/bulk-settle — settle the selected claims together, in list order, each by the
# rules of settling one (a claim gone to PENDING counts as settled); each that cannot be settled is left as
# it is. Responds with how many were settled and how many refused.
settle:
  class: net.officefloor.hq.app.claim.BulkSettleClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkSettle
